// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AsyncDNSResolver
 * @notice Resolves DNS records with async callback pattern and temporary storage
 * @dev Uses temporary storage slots for pending resolutions before finalization
 */
contract AsyncDNSResolver is Ownable {
    struct Resolution {
        bytes32 queryHash;
        address requester;
        uint256 timestamp;
        bool finalized;
        bytes result;
    }

    struct TempSlot {
        bytes32 slotId;
        uint256 expiry;
        bool active;
        address creator;
    }

    mapping(bytes32 => Resolution) public resolutions;
    mapping(bytes32 => TempSlot) public tempSlots;
    mapping(address => bool) public authorizedOracles;

    uint256 public constant SLOT_DURATION = 300; // 5 minutes
    uint256 public nonce;

    event ResolutionRequested(bytes32 indexed queryId, string domain);
    event TempSlotCreated(bytes32 indexed slotId, uint256 expiry);
    event ResolutionFinalized(bytes32 indexed queryId, bytes result);
    event SlotReclaimed(bytes32 indexed slotId);

    modifier onlyOracle() {
        require(authorizedOracles[msg.sender], "Not authorized oracle");
        _;
    }

    constructor() Ownable(msg.sender) {}

    function addOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = true;
    }

    function removeOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = false;
    }

    /**
     * @notice Creates a temporary storage slot for pending DNS resolution
     * @dev Slot ID derived from commit-reveal entropy for uniqueness
     * @param domain The domain name to resolve
     * @return queryId The unique identifier for this resolution request
     */
    function requestResolution(string calldata domain) external returns (bytes32 queryId) {
        // Generate slot ID using unpredictable combination
        bytes32 slotId = _generateTempSlotId(domain);

        queryId = keccak256(abi.encodePacked(domain, msg.sender, block.timestamp));

        // Create temporary slot for async callback
        tempSlots[slotId] = TempSlot({
            slotId: slotId,
            expiry: block.timestamp + SLOT_DURATION,
            active: true,
            creator: msg.sender
        });

        resolutions[queryId] = Resolution({
            queryHash: slotId,
            requester: msg.sender,
            timestamp: block.timestamp,
            finalized: false,
            result: ""
        });

        emit ResolutionRequested(queryId, domain);
        emit TempSlotCreated(slotId, block.timestamp + SLOT_DURATION);
        return queryId;
    }

    /**
     * @notice Oracle callback to fulfill DNS resolution into temp slot
     * @param queryId The query to fulfill
     * @param result The DNS resolution result
     */
    function fulfillResolution(bytes32 queryId, bytes calldata result) external onlyOracle {
        Resolution storage res = resolutions[queryId];
        require(!res.finalized, "Already finalized");
        require(res.timestamp != 0, "Query does not exist");

        TempSlot storage slot = tempSlots[res.queryHash];
        require(slot.active, "Temp slot expired or inactive");

        // Write result to resolution
        res.result = result;
        res.finalized = true;

        emit ResolutionFinalized(queryId, result);
    }

    /**
     * @notice Reclaim expired temporary slots
     * @dev Anyone can reclaim expired slots - strict expiry enforcement
     * @param slotId The slot to reclaim
     */
    function reclaimSlot(bytes32 slotId) external {
        TempSlot storage slot = tempSlots[slotId];
        require(slot.active, "Slot not active");
        // Safe: slot must be strictly past expiry before reclaim is allowed
        require(block.timestamp >= slot.expiry + 60, "Slot not yet expired");

        slot.active = false;
        emit SlotReclaimed(slotId);
    }

    /**
     * @notice Generate temp slot ID - uses strong entropy
     * @dev Includes prevrandao for post-merge unpredictability
     */
    function _generateTempSlotId(string calldata domain) internal returns (bytes32) {
        // Unpredictable slot ID using prevrandao (post-merge beacon chain randomness)
        nonce++;
        return keccak256(abi.encodePacked(
            block.prevrandao,
            nonce,
            msg.sender,
            domain
        ));
    }

    /**
     * @notice Retrieve resolution result
     * @param queryId The query identifier
     * @return The resolution bytes
     */
    function getResolution(bytes32 queryId) external view returns (bytes memory) {
        Resolution storage res = resolutions[queryId];
        require(res.finalized, "Not yet resolved");
        return res.result;
    }

    /**
     * @notice Check if a temp slot is still valid for writing
     * @param slotId The slot to check
     */
    function isSlotValid(bytes32 slotId) external view returns (bool) {
        TempSlot storage slot = tempSlots[slotId];
        return slot.active && block.timestamp <= slot.expiry;
    }

    /**
     * @notice Emergency: owner can invalidate any slot
     */
    function emergencyInvalidateSlot(bytes32 slotId) external onlyOwner {
        tempSlots[slotId].active = false;
    }
}
